export const title = "How to Choose a Webcam for a Tight Space Behind Your Chair";
export const metaTitle = "How to Choose a Webcam for a Tight Space Behind";
export const metaDescription = "Choose a webcam for a tight room by testing camera distance, framing, privacy, mounting, and the actual application. A research-based guide from DeskFinds.";
export const author = "Jamie Cole, Lead Product Researcher";
export const datePublished = "2026-11-17";
